/* ── Informasi Model untuk Firmware ── */
#define MODEL_INPUT_SIZE      5      /* jam, cuaca, daya_surya, toren_persen, suhu_heater */
#define MODEL_OUTPUT_SIZE     1      /* probabilitas pengalihan (0.0 - 1.0) */
#define MODEL_TENSOR_ARENA    4096   /* Ukuran arena tensor (bytes) — sesuaikan jika perlu */

/*
 * ── Mapping Probabilitas ke Threshold Register ──
 * Contoh konversi probabilitas AI → nilai THRESHOLD_REG:
 *
 *   Probabilitas  |  Threshold (Watt)  |  Aksi
 *   ------------- | ------------------ | --------
 *   >= 0.90       |  1000              |  Segera alihkan
 *   >= 0.70       |  1500              |  Alihkan moderat
 *   >= 0.50       |  2000              |  Alihkan ringan
 *   <  0.50       |  3000 (max)        |  Normal/tidak alihkan
 *
 * Rumus: threshold = MAX_THRESHOLD - (prob * (MAX_THRESHOLD - MIN_THRESHOLD))
 *        threshold = 3000 - (prob * 2000)
 *
 * Threshold ditulis ke THRESHOLD_REG pada offset 0x08
 * melalui APB bus: PADDR=4'h8, PWRITE=1, PWDATA=[threshold]
 */
#define THRESHOLD_REG_OFFSET  0x08
#define MAX_THRESHOLD_WATT    3000
#define MIN_THRESHOLD_WATT    1000

/* Macro konversi probabilitas → threshold */
#define PROB_TO_THRESHOLD(prob) \
    (MAX_THRESHOLD_WATT - (unsigned int)((prob) * (MAX_THRESHOLD_WATT - MIN_THRESHOLD_WATT)))

